def rotatedDigits(n):
    # dp[i]: -1 if invalid, 0 if valid but same, 1 if valid and good (changes)
    dp = [0] * (n + 1)
    cnt = 0

    for i in range(1, n + 1):
        if i < 10:
            # Digits 0,1,8 -> valid but unchanged
            if i in (0, 1, 8):
                dp[i] = 0
            # Digits 2,5,6,9 -> valid and change
            elif i in (2, 5, 6, 9):
                dp[i] = 1
                cnt += 1
            # Digits 3,4,7 -> invalid
            else:
                dp[i] = -1
        else:
            a, b = dp[i // 10], dp[i % 10]
            if a == -1 or b == -1:
                dp[i] = -1
            elif a == 1 or b == 1:
                dp[i] = 1
                cnt += 1
            else:
                dp[i] = 0
    return cnt
